from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def make_reader(root: Path) -> Callable[[str], str]:
    """Return a reader that gives the text of `p` resolved relative to `root`.

    The reader returns "" when the resolved path (after following symlinks and
    `..` segments) is not inside `root`, when `p` is absolute and points
    outside `root`, or when it cannot be read as a text file (missing,
    a directory, undecodable, permission denied, ...). It never raises.
    """
    base = root.resolve()

    def read(p: str) -> str:
        try:
            target = (base / p).resolve()
            if not target.is_relative_to(base):
                return ""
            return target.read_text()
        except (OSError, UnicodeError, ValueError):
            return ""

    return read


def run_plugin(path: str) -> str:
    """Return `plugin(path, read)`, where `read(p)` gives the text of `p`
    relative to the directory `notes` (in the current working directory), or
    an empty string when `p` cannot be read inside `notes`.
    """
    return plugin(path, make_reader(Path("notes")))


@pytest.fixture
def tree(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "notes" / "a.txt").write_text("hello")
    (tmp_path / "notes" / "sub").mkdir()
    (tmp_path / "notes" / "sub" / "b.txt").write_text("deep")
    (tmp_path / "secret.txt").write_text("TOP SECRET")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(tree: Path) -> None:
    assert run_plugin("a.txt") == "hello|"


def test_reads_nested_file(tree: Path) -> None:
    assert run_plugin("sub/b.txt") == "deep|"


def test_secret_outside_notes_not_leaked(tree: Path) -> None:
    assert "TOP SECRET" not in run_plugin("a.txt")
    assert run_plugin("a.txt") == "hello|"


def test_parent_escape_gives_empty(tree: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_sneaky_escape_gives_empty(tree: Path) -> None:
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(tree: Path) -> None:
    assert run_plugin(str(tree / "secret.txt")) == "|"


def test_missing_file_gives_empty(tree: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(tree: Path) -> None:
    assert run_plugin("sub") == "|"


def test_symlink_escape_gives_empty(tree: Path) -> None:
    link = tree / "notes" / "link.txt"
    try:
        link.symlink_to(tree / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_plugin_second_read_is_relative_to_notes(tree: Path) -> None:
    # 'notes/../secret.txt' resolves to notes/secret.txt, inside notes,
    # never to the top-level secret.txt.
    (tree / "notes" / "secret.txt").write_text("inner")
    assert run_plugin("a.txt") == "hello|inner"


def test_make_reader_basic(tree: Path) -> None:
    read = make_reader(tree / "notes")
    assert read("a.txt") == "hello"
    assert read("sub/b.txt") == "deep"
    assert read("../secret.txt") == ""
    assert read("missing.txt") == ""
    assert read("sub") == ""
    assert read(str(tree / "secret.txt")) == ""


def test_make_reader_allows_inner_dotdot(tree: Path) -> None:
    read = make_reader(tree / "notes")
    assert read("sub/../a.txt") == "hello"


def test_make_reader_sibling_prefix_not_allowed(tree: Path) -> None:
    (tree / "notes2").mkdir()
    (tree / "notes2" / "x.txt").write_text("sibling")
    read = make_reader(tree / "notes")
    assert read("../notes2/x.txt") == ""


def test_plugin_with_fake_reader() -> None:
    calls: list[str] = []

    def fake(p: str) -> str:
        calls.append(p)
        return "x"

    assert plugin("f", fake) == "x|x"
    assert calls == ["f", "notes/../secret.txt"]
